const beats=[['A strange arrival','The first clue','A warning in the dark','The unexpected ally','A locked passage','The other side','A hidden message','A difficult promise','Footsteps nearby','A second route','The missing piece','A risky meeting','What the map concealed','A change of plans','A voice from the past','The quiet room','An uneasy bargain','The truth emerges','The last safe place','The broken signal','A new witness','Beneath the surface','The cost of waiting','A sudden return','A narrow escape','The final clue','The point of no return','One more secret','The last decision']];
function buildFromIdea({idea,genre,hero,length,tone}){const theme=generationThemes[genre]||generationThemes['Create Your Own'],count=length==='Long'?29:length==='Medium'?15:5,endCount=length==='Long'?4:3,setting=(idea.match(/(?:set in|on|beneath|inside|at)\s+([^.!?]+)/i)?.[1]||theme.place).trim().slice(0,60),heroName=hero.trim()||'The traveller',trimIdea=idea.trim().replace(/[.!?]+$/,'');const titles=['The Keeper','The Explorer','The Escape','The Secret'];const sceneText=(i)=>{const seed=i===0?`${trimIdea}.`:`In ${setting}, ${heroName} reaches ${theme.place}.`;const situation=[`A trace of the ${theme.object} appears where it should not be.`,`The ${theme.ally} offers help, but asks for a promise.`,`A sign points toward ${theme.threat}.`,`An old path opens, revealing another side of the story.`,`Someone has been here just moments before.`,`A new discovery changes what ${heroName} believed.`,`The next clue is guarded by a difficult decision.`][i%7];return `${seed} ${situation} ${tone==='Scary'?'A sound behind you grows closer.':tone==='Funny'?'Naturally, things become more complicated.':tone==='Epic'?'The fate of this place may depend on what happens next.':'Something important is still hidden.'}`};const scenes=Array.from({length:count},(_,i)=>({id:`g${i}`,title:i===0?'The beginning':beats[0][(i-1)%beats[0].length],text:sceneText(i),dialogue:i%4===2?'We cannot ignore this.':'',speaker:i%4===2?theme.ally:'',supporting:i%4===2?'Companion':'None',question:i%3===0?'Which path will you take?':'What do you do?',background:['Forest','Valley','Cavern','Desert'][Math.floor(i/4)%4],portrait:i%5===3?'Companion':i%7===4?'Explorer':'Traveller',motion:['Stars','Clouds','Flicker','Rain'][i%4],sound:i%5===0?'Chime':'None',type:'scene',choices:[]}));const endings=Array.from({length:endCount},(_,i)=>({id:`ge${i}`,title:titles[i],text:[`${heroName} helps ${theme.ally} protect ${setting}. The story of their choice is remembered.`,`${heroName} follows the clues beyond ${setting}, carrying the ${theme.object} toward a new horizon.`,`${heroName} escapes ${theme.threat}, but one mystery remains for another day.`,`${heroName} discovers what was hidden from everyone else and changes the future of ${setting}.`][i],dialogue:'',question:'',background:['Valley','Desert','Forest','Cavern'][i],portrait:i===1?'Explorer':'Traveller',motion:'Stars',sound:'Chime',type:'ending',choices:[]}));for(let i=0;i<count;i++){const targetA=i===count-1?endings[0].id:`g${i+1}`,targetB=i>=count-endCount?endings[i-(count-endCount)].id:`g${i+2}`;scenes[i].choices=[{id:`ga${i}`,text:i%3===0?'Ask for help and investigate':i%3===1?'Follow the clue':'Take the careful route',target:targetA,effects:[{kind:'trait',key:'Empathy',amount:1}]},{id:`gb${i}`,text:i%3===0?'Go alone and take a risk':i%3===1?'Search another way':'Confront the danger',target:targetB,effects:[{kind:'trait',key:'Courage',amount:1}]}]}return {version:2,title:trimIdea.length<40?trimIdea.replace(/^a\s+/i,'').replace(/^./,c=>c.toUpperCase()):`The ${genre==='Create Your Own'?'Story':genre} Adventure`,genre,world:setting.replace(/^./,c=>c.toUpperCase()),description:trimIdea,hook:`What will ${heroName} discover?`,music:genre==='Sci-Fi'?'Cosmic':genre==='Mystery'?'Mystery':genre==='Fantasy'?'Enchanted':'Dungeon',heroName,heroDescription:'A traveller caught in an unexpected adventure.',heroPersonality:'Curious',heroGoal:`Discover the truth about ${theme.object}`,portrait:'Traveller',background:'Forest',customPortrait:'',customBackground:'',opening:'g0',scenes:[...scenes,...endings]}}

function loadDraft(){try{const value=JSON.parse(localStorage.getItem('storyforge-draft'));if(value?.scenes?.length){const ids=new Set(value.scenes.map(s=>s.id));let repaired=false;for(const s of value.scenes){const choices=s.choices||[];s.choices=choices.filter(c=>ids.has(c.target)&&c.target!==s.id);if(s.choices.length!==choices.length)repaired=true}if(repaired)localStorage.setItem('storyforge-draft',JSON.stringify(value));return value}}catch{}return blank()}
function save(){try{localStorage.setItem('storyforge-draft',JSON.stringify(project))}catch{}const status=$('.draft-status');if(status)status.textContent='Unsaved changes · choose Save story'}
const scene=id=>project.scenes.find(s=>s.id===id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=prefix=>prefix+Math.random().toString(36).slice(2,9);
function toast(msg){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500)}
function field(label,key,value,textarea=false,extra=''){return `<div class="field"><label for="${key}">${label}</label>${textarea?`<textarea id="${key}" data-project="${key}" ${extra}>${escape(value)}</textarea>`:`<input id="${key}" data-project="${key}" value="${escape(value)}" ${extra}>`}</div>`}
function header(){if(view==='play'||view==='title'||view==='featured-list')return '';return `<header class="topbar"><button type="button" class="brand brand-home" data-action="title" aria-label="Storyforge home"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 32 32" xmlns="http://www.w3.org/2000/svg" shape-rendering="crispEdges"><path fill="#000" d="M0 0h32v32H0z"/><path fill="#00d8e8" d="M3 8h4V6h17v2h4v8h-4v2H7v-2H3z"/><path fill="#fff15a" d="M8 8h16v3H8zM14 16h6v3h-6z"/><path fill="#3945c8" d="M7 13h17v3H7zM14 19h6v10h-6z"/><path fill="#f761d5" d="M14 19h2v10h-2z"/><path fill="#00d8e8" d="M13 29h8v2h-8z"/></svg></span><span>Storyforge</span></button><div class="top-actions"><button class="btn ghost menu-music-btn" data-action="music-toggle" aria-pressed="${musicEnabled}" aria-label="${musicEnabled?'Mute music':'Play music'}">${musicEnabled?'♫ Music on':'♪ Play music'}</button>${view==='start'||view==='idea'||view==='ready'?`<button class="btn ghost" data-action="guide">How it works</button>`:view==='edit'?`<button class="btn ghost" data-action="guide">How to create your story</button><button class="btn ghost" data-action="new">New story</button><button class="btn" data-action="save-story">Save story</button><button class="btn" data-action="play">▶ Play my game</button>`:`<button class="btn ghost" data-action="${published?'create':'edit'}">${published?'Create your own':'← Back to editor'}</button>${!published?`<button class="btn" data-action="restart">Restart</button>`:''}`}</div></header>`}
function render(){clearTimeout(narrationTimer);narrationToken++;app.innerHTML=header()+(view==='title'?titlePage():view==='featured-list'?featuredList():view==='start'?startPage():view==='idea'?ideaPage():view==='ready'?readyPage():view==='edit'?editor():player());bind();if(view==='start')refreshCloudDrafts();applyAssetColours();if(view==='edit'){requestAnimationFrame(drawEasyLines)}if(view==='play')startNarration();syncMusic()}
function titlePage(){return `<main class="title-screen"><div class="title-art" aria-hidden="true"></div><div class="title-top"><span class="title-brand"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 32 32" xmlns="http://www.w3.org/2000/svg" shape-rendering="crispEdges"><path fill="#000" d="M0 0h32v32H0z"/><path fill="#00d8e8" d="M3 8h4V6h17v2h4v8h-4v2H7v-2H3z"/><path fill="#fff15a" d="M8 8h16v3H8zM14 16h6v3h-6z"/><path fill="#3945c8" d="M7 13h17v3H7zM14 19h6v10h-6z"/><path fill="#f761d5" d="M14 19h2v10h-2z"/><path fill="#00d8e8" d="M13 29h8v2h-8z"/></svg></span> Storyforge</span><button class="btn ghost menu-music-btn" data-action="music-toggle" aria-pressed="${musicEnabled}" aria-label="${musicEnabled?'Mute music':'Play music'}">${musicEnabled?'♫ Music on':'♪ Play music'}</button></div><div class="title-content"><h1>Stories you make.<br>Adventures you play.</h1><p>Choose a featured adventure, or build an adventure of your own.</p><div class="title-actions"><button class="title-action title-create" data-action="create-game"><span class="eyebrow">Your story begins here</span><strong>Create Game</strong><span>Write scenes, choices and endings for friends to play.</span><span class="title-arrow">→</span></button><button class="title-action title-play" data-action="featured-games"><span class="eyebrow">Featured adventures</span><strong>Play Game</strong><span>Choose a story for your next adventure</span><span class="title-arrow">→</span></button></div></div></main>`}
function readingLevel(stars){return `Reading Level: <span role="img" aria-label="${stars} out of 5 stars" style="font-family:system-ui,sans-serif;font-size:1.25em;letter-spacing:.12em;white-space:nowrap">${'★'.repeat(stars)}</span>`}
function featuredList(){return `<main class="featured-picker"><div class="picker-top"><button class="btn ghost" data-action="title">← Title</button><button type="button" class="title-brand title-brand-home" data-action="title" aria-label="Storyforge home"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 32 32" xmlns="http://www.w3.org/2000/svg" shape-rendering="crispEdges"><path fill="#000" d="M0 0h32v32H0z"/><path fill="#00d8e8" d="M3 8h4V6h17v2h4v8h-4v2H7v-2H3z"/><path fill="#fff15a" d="M8 8h16v3H8zM14 16h6v3h-6z"/><path fill="#3945c8" d="M7 13h17v3H7zM14 19h6v10h-6z"/><path fill="#f761d5" d="M14 19h2v10h-2z"/><path fill="#00d8e8" d="M13 29h8v2h-8z"/></svg></span> Storyforge</button><button class="btn ghost menu-music-btn" data-action="music-toggle" aria-pressed="${musicEnabled}">${musicEnabled?'♫ Music on':'♪ Play music'}</button></div><div class="picker-content"><div class="eyebrow">Featured adventures</div><h1>Choose your story</h1><p>Every choice takes the story somewhere new.</p><div class="picker-grid"><button class="adventure-card" data-action="play-featured"><img src="/assets/crown-road.webp" alt="A rider travels toward a dark castle"><span class="card-info"><small>DARK FANTASY · ${readingLevel(5)}</small><strong>The Crown of Ash</strong><span>Carry the king’s warning into a kingdom of secrets and difficult choices.</span><em>Play adventure →</em></span></button><button class="adventure-card" data-action="play-pip"><img src="/assets/pip-village.webp" alt="Pip sets out from Pebblewick toward Dragon Castle"><span class="card-info"><small>COSY FANTASY · ${readingLevel(1)}</small><strong>Pip and the Sleeping Dragon</strong><span>Meet new friends and help a sleepy dragon bring back the morning.</span><em>Play adventure →</em></span></button><button class="adventure-card" data-action="play-city"><img src="/assets/city-roof.webp" alt="Rowan and friends watch a falling star over Asterfall"><span class="card-info"><small>FANTASY MYSTERY · ${readingLevel(4)}</small><strong>The City Below</strong><span>A missing mother, a buried city, and a machine that can change memories. Who will you trust?</span><em>Play adventure →</em></span></button><button class="adventure-card" data-action="play-clock"><img src="/assets/clock-kingdom.webp" alt="Bellhaven frozen at 10:17 beneath its giant castle clock"><span class="card-info"><small>MAGICAL FANTASY · ${readingLevel(3)}</small><strong>The Clockwork Kingdom</strong><span>Time has stopped. Follow a golden key, find the Heart Gear, and choose Bellhaven’s future.</span><em>Play adventure →</em></span></button><button class="adventure-card" data-action="play-blackwater"><img src="/assets/blackwater-shore.webp" alt="A bell tower rises from Blackwater Lake beside Morrowfen"><span class="card-info"><small>DARK FANTASY · ${readingLevel(5)}</small><strong>The Bells Beneath Blackwater</strong><span>A drowned city calls your name. Decide who to trust before the seventh bell rings.</span><em>Play adventure →</em></span></button><button class="adventure-card" data-action="play-moonberry"><img src="/assets/moonberry-home.webp" alt="Pip sets out from a forest home to find the Moonberries"><span class="card-info"><small>COSY FANTASY · ${readingLevel(1)}</small><strong>The Moonberry Picnic</strong><span>Follow the berry trail, meet new friends, and help Muffin the dragon feel welcome.</span><em>Play adventure →</em></span></button></div></div></main>`}
function startPage(){return `<main class="start-screen"><div class="start-art"></div><div class="start-content"><div class="eyebrow">A story game studio</div><h1>Make an adventure your friends can play.</h1><p>Start with a few connected story blocks. Click any block to change the story, then grow it with scenes and endings.</p><div class="start-options"><button class="start-option" data-action="start-easy"><span class="eyebrow">Your story starts here</span><strong>Create your story</strong><span>Add as many scenes, characters and choices as you like.</span><span class="option-arrow">→</span></button></div><div class="cloud-drafts"><h2>Stories in progress</h2><div id="cloud-drafts-list">Loading your stories…</div></div></div></main>`}
function ideaPage(){return `<main class="idea-screen"><div class="idea-panel"><div class="eyebrow">Start with an idea</div><h1>What kind of adventure do you want to create?</h1><p class="muted">We’ll build a complete branching draft. You can rewrite every scene and choice.</p><div class="field"><label for="ideaInput">Your idea</label><textarea id="ideaInput" placeholder="Teenagers discover an abandoned arcade beneath their school."></textarea></div><div class="field-grid"><div class="field"><label for="ideaGenre">Genre</label><select id="ideaGenre">${genres.map(g=>`<option>${g}</option>`).join('')}</select></div><div class="field"><label for="ideaHero">Main character (optional)</label><input id="ideaHero" placeholder="The new student"></div><div class="field"><label for="ideaLength">Length</label><select id="ideaLength"><option>Short</option><option>Medium</option><option>Long</option></select></div><div class="field"><label for="ideaTone">Tone</label><select id="ideaTone">${['Mysterious','Funny','Dark','Epic','Strange','Scary'].map(t=>`<option>${t}</option>`).join('')}</select></div></div><div class="inline-actions"><button class="btn primary" data-action="build-idea">Build my game →</button><button class="btn ghost" data-action="home">← Back</button></div></div></main>`}
function readyPage(){return `<main class="idea-screen"><div class="idea-panel"><div class="eyebrow">Your adventure is ready</div><h1>${escape(project.title)}</h1><p>${escape(project.description)}</p><p class="muted">${project.scenes.length} scenes · ${project.scenes.filter(s=>s.type==='ending').length} endings · Every part can be changed.</p><div class="inline-actions"><button class="btn primary" data-action="play">▶ Play the game</button><button class="btn" data-action="edit-ready">Edit the story →</button></div></div></main>`}
function editor(){return easyEditor()}
function setBlockType(block,type){
 if(!block||block.id===project.opening||block.type===type)return;
 if(type==='ending'){
  block.savedChoices=block.choices||[];
  block.choices=[];
  block.type='ending';
 }else{
  block.type='scene';
  block.choices=block.savedChoices||[];
  delete block.savedChoices;
  if(!block.choices.length){
   for(let i=0;i<2;i++){
    const choice={id:id('c'),text:i===0?'Take the first path':'Try another way',target:'',effects:[]};
    block.choices.push(choice);
    createChoiceDestination(block,choice,true);
   }
  }
 }
 save();render();
}
function appendEasyBranch(source,type){
 if(!source)return;
 const wasEnding=source.type==='ending';
 if(wasEnding){source.type='scene';source.choices=source.savedChoices||[];delete source.savedChoices}
 const choice={id:id('c'),text:type==='ending'?'Choose the final path':'Explore what happens next',target:'',effects:[]};
 source.choices.push(choice);
 const next=createChoiceDestination(source,choice,type==='ending');
 selected=next.id;save();render();
 document.querySelector('#easy-block-editor')?.scrollIntoView({behavior:'smooth',block:'start'});
 if(wasEnding)toast('This box is now a scene so the story can continue.');
}
function deleteEasyBox(boxId){
 if(boxId===project.opening)return;
 const target=scene(boxId);if(!target)return;
 const descendants=new Set(),queue=[boxId];
 while(queue.length){const next=queue.shift();if(descendants.has(next))continue;descendants.add(next);for(const choice of scene(next)?.choices||[])if(scene(choice.target))queue.push(choice.target)}
 const reachable=new Set(),fromOpening=[project.opening];
 while(fromOpening.length){const next=fromOpening.shift();if(reachable.has(next)||next===boxId)continue;reachable.add(next);for(const choice of scene(next)?.choices||[])if(choice.target!==boxId&&scene(choice.target))fromOpening.push(choice.target)}
 const removed=new Set([...descendants].filter(key=>!reachable.has(key)));
 const message=removed.size>1?`Delete “${target.title}” and ${removed.size-1} boxes that only follow it?`:`Delete “${target.title}” and the choices leading to it?`;
 if(!confirm(message))return;
 const parent=project.scenes.find(s=>s.choices?.some(c=>c.target===boxId)&&!removed.has(s.id));
 project.scenes=project.scenes.filter(s=>!removed.has(s.id));
 for(const block of project.scenes){block.choices=(block.choices||[]).filter(c=>!removed.has(c.target));if(block.savedChoices)block.savedChoices=block.savedChoices.filter(c=>!removed.has(c.target))}
 selected=parent?.id||project.opening;save();render();toast(removed.size===1?'Box deleted':`${removed.size} boxes deleted`);
}
function storyHealth(){const reachable=new Set(),queue=[project.opening];while(queue.length){const sid=queue.shift();if(reachable.has(sid))continue;reachable.add(sid);for(const c of scene(sid)?.choices||[])if(scene(c.target))queue.push(c.target)}const endings=project.scenes.filter(x=>x.type==='ending'),dead=project.scenes.filter(x=>x.type==='scene'&&!(x.choices||[]).length),orphans=project.scenes.filter(x=>!reachable.has(x.id));return {reachable,endings,dead,orphans,ready:endings.length>0&&dead.length===0&&orphans.length===0}}
function storyHealthMarkup(){const h=storyHealth(),status=h.ready?'Ready to play':h.endings.length?'Needs a little work':'Add an ending';return `<div class="story-health ${h.ready?'ready':''}"><strong>${status}</strong><span>${h.reachable.size} connected · ${h.endings.length} ending${h.endings.length===1?'':'s'}${h.dead.length?` · ${h.dead.length} unfinished path${h.dead.length===1?'':'s'}`:''}${h.orphans.length?` · ${h.orphans.length} unconnected box${h.orphans.length===1?'':'es'}`:''}</span></div>`}
function easyEditor(){
 const opening=scene(project.opening),active=scene(selected)||opening;
 const sceneField=(s,key,label,rows=false)=>`<div class="field"><label for="easy-${s.id}-${key}">${label}</label>${rows?`<textarea id="easy-${s.id}-${key}" data-easy-id="${s.id}" data-easy-field="${key}">${escape(s[key]||'')}</textarea>`:`<input id="easy-${s.id}-${key}" data-easy-id="${s.id}" data-easy-field="${key}" value="${escape(s[key]||'')}">`}</div>`;
 const visual=s=>`<div class="easy-picture"><img src="${escape(background(s))}" alt="${escape(assetName('location',s.background||project.background))}"><img src="${escape(portrait(s))}" alt="${escape(assetName('character',s.portrait||project.portrait))}"></div><div class="field-grid"><div class="field"><label for="easy-${s.id}-place">Place</label><select id="easy-${s.id}-place" data-easy-visual="background" data-easy-id="${s.id}">${Object.keys(backdrops).map(k=>`<option value="${escape(k)}" ${s.background===k?'selected':''}>${escape(assetName('location',k))}</option>`).join('')}</select></div><div class="field"><label for="easy-${s.id}-character">Character</label><select id="easy-${s.id}-character" data-easy-visual="portrait" data-easy-id="${s.id}">${Object.keys(portraits).map(k=>`<option value="${escape(k)}" ${s.portrait===k?'selected':''}>${escape(assetName('character',k))}</option>`).join('')}</select></div></div>`;
 const card=(s,label)=>`<div class="easy-story-block ${s.type==='ending'?'ending':''}"><button type="button" class="easy-story-card ${s.type==='ending'?'ending':''} ${active.id===s.id?'selected':''}" data-easy-edit="${s.id}" aria-label="Edit ${escape(label)}: ${escape(s.title)}" ${active.id===s.id?'aria-current="true"':''}><span class="easy-story-art"><img src="${escape(background(s))}" alt=""><img src="${escape(portrait(s))}" alt=""></span><span class="easy-story-copy"><em>${escape(label)}</em><strong data-easy-card-title="${s.id}">${escape(s.title)}</strong><span data-easy-card-description="${s.id}">${escape(s.text||'Click to write this part of the story.')}</span><small>${escape(assetName('location',s.background||project.background))} · ${escape(assetName('character',s.portrait||project.portrait))}</small><span class="easy-edit-hint">Click to edit →</span></span></button><div class="easy-block-actions" aria-label="Grow the story after ${escape(s.title)}"><button type="button" data-easy-append="scene" data-easy-source="${s.id}">＋ Add scene</button><button type="button" data-easy-append="ending" data-easy-source="${s.id}">＋ Add ending</button>${s.id!==project.opening?`<button type="button" class="easy-delete" data-easy-delete="${s.id}" aria-label="Delete ${escape(s.title)}">Delete box</button>`:''}</div></div>`;
 const tree=(s,path=new Set(),depth=0)=>{
  if(path.has(s.id)||depth>8)return `<div class="easy-tree-return"><button class="btn sm" data-easy-edit="${s.id}">↪ ${escape(s.title)}</button></div>`;
  const nextPath=new Set(path);nextPath.add(s.id);
  const branches=s.type==='scene'?(s.choices||[]).map((choice,i)=>({choice,number:i+1,dest:scene(choice.target)})).filter(x=>x.dest):[];
  return `<div class="easy-tree-node">${card(s,s.id===project.opening?'START · OPENING SCENE':s.type==='ending'?'ENDING':'SCENE')}${branches.length?`<div class="easy-tree-children" style="--easy-branches:${branches.length}">${branches.map(({choice,number,dest})=>`<div class="easy-tree-child"><button type="button" class="easy-story-link" data-easy-edit="${s.id}" data-easy-link="${choice.id}" aria-label="Edit choice ${number}: ${escape(choice.text)}"><span>CHOICE ${number}</span><strong data-easy-choice-label="${choice.id}">${escape(choice.text||'Write a choice')}</strong><span aria-hidden="true">↓</span></button>${tree(dest,nextPath,depth+1)}</div>`).join('')}</div>`:''}</div>`;
 };
 const choices=active.type==='scene'?`<div class="easy-choice-fields"><h3>What can the player choose?</h3><p class="muted">Good choices change what happens next — not just the wording.</p>${(active.choices||[]).map((choice,i)=>{const dest=scene(choice.target);return `<div class="easy-choice-field"><label for="easy-choice-${choice.id}">Choice ${i+1} → ${escape(dest?.title||'Next box')}</label><input id="easy-choice-${choice.id}" data-easy-choice="${choice.id}" value="${escape(choice.text)}"><button type="button" class="btn sm" data-easy-edit="${escape(choice.target)}">Edit next box →</button></div>`}).join('')}<p class="muted">To add another path, use ＋ Add scene or ＋ Add ending beneath this box on the map.</p></div>`:'';
 return `<main class="easy-shell"><div class="eyebrow">Create your story · Story map</div><div class="easy-map-head"><div><h1>Make your story</h1><p>Click a box to edit it. Choose Scene to keep the adventure going, or Ending to finish a path.</p></div><div class="easy-controls"><span class="draft-status">Save your story in Storyforge</span><button class="btn" data-action="save-story">Save story</button><button class="btn" data-action="fit-map">◎ Fit story map</button><button class="btn primary" data-action="play">▶ Play game</button><button class="btn" data-action="publish">Share game →</button></div></div>${storyHealthMarkup()}<div class="easy-story-map" aria-label="Story map with choices connected to the next scene or ending"><svg id="easy-map-lines" aria-hidden="true"></svg>${tree(opening)}</div><section class="easy-panel easy-block-editor" id="easy-block-editor" aria-label="Edit story block"><div class="easy-edit-heading"><div><span class="eyebrow">${active.id===opening.id?'Opening scene':active.type==='ending'?'Ending':'Scene'}</span><h2>Edit ${active.id===opening.id?'the opening':'this box'}</h2></div><span>Changes appear on the map above</span></div>${active.id===opening.id?`${field('Name your game','title',project.title)}${field('Hero’s name','heroName',project.heroName)}`:`<div class="easy-type-field"><strong>What kind of box is this?</strong><div class="easy-type-actions"><button type="button" class="btn ${active.type==='scene'?'primary':''}" data-easy-type="scene" data-easy-id="${active.id}" aria-pressed="${active.type==='scene'}">Scene · keep going</button><button type="button" class="btn ${active.type==='ending'?'primary':''}" data-easy-type="ending" data-easy-id="${active.id}" aria-pressed="${active.type==='ending'}">Ending · finish here</button></div></div>`}${sceneField(active,'title',active.type==='ending'?'Ending title':'Scene title')}${sceneField(active,'text',active.type==='ending'?'What happens at the end?':'What happens here?',true)}${active.type==='scene'?sceneField(active,'question','Question for the player')+choices:''}${visual(active)}${sceneEffectPicker(active,true)}<details class="optional easy-customise"><summary>Edit place and character colours, names and details</summary>${assetSettings('location',active.background||project.background)}${assetSettings('character',active.portrait||project.portrait)}</details><details class="optional"><summary>Music for your adventure</summary><label for="easy-music">Soundtrack</label><select id="easy-music" data-project="music">${musicTracks.map(x=>`<option ${project.music===x?'selected':''}>${x}</option>`).join('')}</select><p class="music-preview-note" id="music-preview-status" aria-live="polite">${musicEnabled?`♫ Previewing ${escape(project.music)}`:'Music is off — turn it on to hear this theme'}</p></details><div class="easy-controls">${active.id!==opening.id?`<button class="btn" data-easy-edit="${opening.id}">← Edit the opening</button>`:''}<button class="btn primary" data-action="play">▶ Play my game</button></div></section></main>`;
}
function mainContent(){switch(stage){
case 'World':return `<h1>World and characters</h1><p class="lead">Name your adventure and choose where it takes place. You can change all of this later.</p><div class="card guide-card"><div><h3>New here? Start small.</h3><p>One opening, two choices and two endings make a complete first game.</p></div><button class="btn" data-action="guide">How it works</button></div><div class="card">${field('Your game’s title','title',project.title)}<div class="field-grid">${field('World name','world',project.world)}${field('A question for your friends','hook',project.hook)}</div><label>Pick a genre</label><div class="pills">${genres.map(g=>`<button class="pill ${project.genre===g?'selected':''}" data-genre="${g}">${g}</button>`).join('')}</div></div><div class="card"><h3>Create the hero</h3>${field('Hero name','heroName',project.heroName||'')}${field('What do they want?','heroGoal',project.heroGoal||'')}<details class="optional"><summary>Personality and description</summary>${field('Personality','heroPersonality',project.heroPersonality||'')}${field('Description','heroDescription',project.heroDescription||'',true)}</details></div><div class="card"><h3>Music for your adventure</h3><p class="muted">Choose a looping dungeon synth theme. You can change it for individual scenes.</p><div class="field"><label for="worldMusic">Default soundtrack</label><select id="worldMusic" data-project="music">${musicTracks.map(x=>`<option ${project.music===x?'selected':''}>${x}</option>`).join('')}</select><p class="music-preview-note" id="music-preview-status" aria-live="polite">${project.music==='None'?'No soundtrack selected':musicEnabled?`♫ Previewing ${escape(project.music)}`:'Music is off — turn it on to hear this theme'}</p></div></div><div class="card"><h3>Pick a background</h3><div class="field"><label for="backgroundSearch">Find a place</label><input id="backgroundSearch" data-asset-filter="world-backgrounds" placeholder="Search ${Object.keys(backdrops).length} locations…"></div><div class="asset-grid asset-library" id="world-backgrounds">${Object.entries(backdrops).map(([name,file])=>`<button class="asset world-asset ${project.background===name?'selected':''}" data-background="${name}"><img src="assets/${file}" alt=""><span data-asset-name-view="location:${escape(name)}">${escape(assetName('location',name))}</span></button>`).join('')}</div>${assetSettings('location',project.background)}<details class="optional"><summary>Describe your world</summary>${field('Describe your world','description',project.description,true)}</details><h3>Pick a character</h3><div class="field"><label for="characterSearch">Find a character</label><input id="characterSearch" data-asset-filter="world-characters" placeholder="Search ${Object.keys(portraits).length} characters…"></div><div class="asset-grid asset-library" id="world-characters">${Object.entries(portraits).map(([name,file])=>`<button class="asset ${project.portrait===name?'selected':''}" data-portrait="${name}"><img src="assets/${file}" data-tint-kind="character" data-tint-key="${escape(name)}" alt=""><span data-asset-name-view="character:${escape(name)}">${escape(assetName('character',name))}</span></button>`).join('')}</div>${assetSettings('character',project.portrait)}</div><div class="inline-actions"><button class="btn primary" data-stage="Story">← Back to story map</button><button class="btn ghost" data-action="example">Explore the example</button></div>`;
case 'Story':{let s=selected?scene(selected):null;return `<div class="section-head"><div><h1>Build your story</h1><p class="lead">Start with these blocks. Click one to write what happens, then connect its choices to the next block.</p></div></div><div class="map-toolbar"><span class="tag">${project.scenes.length} blocks</span><span class="tag">${project.scenes.filter(x=>x.type==='ending').length} endings</span><button class="btn sm" data-action="add-scene">＋ Scene</button><button class="btn sm" data-action="add-ending">＋ Ending</button></div>${mapHTML()}${s?`<div class="card scene-workspace"><div class="block-editor-top"><button class="btn sm ghost" data-action="close-scene">← Story map</button><span class="eyebrow">Editing ${s.id===project.opening?'the opening':s.type==='ending'?'an ending':'a scene'}</span></div>${sceneEditor(s)}${s.type==='scene'?`<div class="section-head"><h3>What can the player do?</h3><button class="btn sm" data-action="add-choice">＋ Add choice</button></div>${choiceEditor(s)}<div class="next-actions"><strong>Grow this branch</strong><p class="muted">Add a block and connect it to this scene.</p><div class="inline-actions"><button class="btn primary" data-action="next-scene">＋ Next scene</button><button class="btn" data-action="next-ending">＋ Ending</button></div></div>`:`<div class="note">This ending completes a path. To change how players reach it, open a scene on the map.</div>`}<details class="optional"><summary>Need a writing nudge?</summary><div class="inline-actions"><button class="btn sm" data-action="assist-continue">Continue story</button><button class="btn sm" data-action="assist-choices">Suggest choices</button><button class="btn sm" data-action="assist-outcome">Another outcome</button><button class="btn sm" data-action="assist-dramatic">More dramatic</button><button class="btn sm" data-action="assist-twist">Add a twist</button><button class="btn sm" data-action="assist-ending">Create ending</button></div></details>${s.id===project.opening?`<details class="optional"><summary>Need an idea for your opening?</summary><div class="inline-actions">${[0,1,2].map(i=>`<button class="btn sm" data-template="${i}">Use idea ${i+1}</button>`).join('')}</div></details>`:''}</div>`:`<div class="map-empty"><strong>Click any block to edit it.</strong><p>The opening is where your friend starts. Each choice points to another scene or an ending.</p><button class="btn primary" data-action="open-opening">Edit the opening →</button></div>`}<div class="bottom-next"><button class="btn primary" data-stage="Test">▶ Play my story</button><button class="btn ghost" data-stage="World">World and characters →</button></div>`}
case 'Test':return `<h1>Try your game</h1><p class="lead">Play as your friend would. Try each path and see whether the ending matches your choices.</p><div class="card"><button class="btn primary" data-action="play">▶ Play my game</button><p class="muted" style="margin:.75rem 0 0">When you finish, choose “Improve a branch” to return to the story.</p></div><div class="card"><h3>Ready to share?</h3>${issues().length?issues().map(x=>`<p>⚑ ${escape(x)}</p>`).join(''):'<p>Every choice has a destination, and your story has an ending.</p>'}<button class="btn" data-stage="Share">Continue to sharing →</button></div>`;
case 'Share':return `<h1>Share your adventure</h1><p class="lead">Your friends open the link and play. They do not need an account.</p><div class="card"><div class="eyebrow">${escape(project.genre)} adventure</div><h2>${escape(project.title)}</h2><p>${escape(project.hook||project.description)}</p><button class="btn primary" data-action="publish">Create play link →</button></div><p class="note">A link saves a snapshot of the story. After making changes, create a new link. Play results stay on each friend's device.</p>`}}
function incoming(id){return project.scenes.reduce((n,s)=>n+s.choices.filter(c=>c.target===id).length,0)}
function mapHTML(){let levels=new Map([[project.opening,0]]),queue=[project.opening];while(queue.length){let sid=queue.shift(),d=levels.get(sid);for(let c of scene(sid)?.choices||[])if(scene(c.target)&&!levels.has(c.target)){levels.set(c.target,Math.min(d+1,8));queue.push(c.target)}}for(let s of project.scenes)if(!levels.has(s.id))levels.set(s.id,Math.max(...levels.values(),0)+1);let columns=[];for(let s of project.scenes)(columns[levels.get(s.id)]??=[]).push(s);return `<div class="map-wrap"><div class="map-board" id="map-board"><svg id="map-lines" aria-hidden="true"></svg>${columns.map((col,i)=>`<div class="map-column">${col.map(s=>`<button class="node ${selected===s.id?'selected':''} ${s.type==='ending'?'ending':''}" data-edit-scene="${s.id}" data-node="${s.id}"><span class="node-picture"><img class="node-place" src="${escape(background(s))}" loading="lazy" alt="">${(s.visual?.actor||s.portrait||project.portrait)!=='None'?`<img class="node-person" src="${escape(portrait(s))}" data-tint-kind="character" data-tint-key="${escape(s.visual?.actor||s.portrait||project.portrait)}" loading="lazy" alt="">`:''}</span><em>${s.id===project.opening?'START':s.type==='ending'?'ENDING':'SCENE'}</em><strong>${escape(s.title)}</strong><span class="node-meta"><span data-asset-name-view="location:${escape(s.visual?.location||s.background||project.background)}">${escape(assetName('location',s.visual?.location||s.background||project.background))}</span> · <span data-asset-name-view="character:${escape(s.visual?.actor||s.portrait||project.portrait)}">${escape(assetName('character',s.visual?.actor||s.portrait||project.portrait))}</span></span><span>${s.type==='ending'?'Final outcome':`${s.choices.length} choice${s.choices.length===1?'':'s'}`}</span>${s.type==='scene'&&s.choices.length?`<span class="node-choice-list">${s.choices.map((c,i)=>`<span data-node-choice="${escape(c.id)}"><b>${i+1}. ${escape(c.text)}</b><small>→ ${escape(scene(c.target)?.title||'Choose next scene')}</small></span>`).join('')}</span>`:''}</button>`).join('')}</div>`).join('')}</div></div>`}
function drawEasyLines(){const board=$('#easy-map-lines')?.parentElement,svg=$('#easy-map-lines');if(!board||!svg)return;const br=board.getBoundingClientRect(),paths=[];const point=(r,side)=>({x:(side==='left'?r.left:r.right)-br.left+board.scrollLeft,y:r.top+r.height/2-br.top+board.scrollTop});for(const link of board.querySelectorAll('[data-easy-link]')){const parent=link.closest('.easy-tree-children')?.parentElement?.querySelector(':scope > .easy-story-block');const child=link.closest('.easy-tree-child')?.querySelector(':scope > .easy-tree-node > .easy-story-block');if(!parent||!child)continue;const a=point(parent.getBoundingClientRect(),'right'),b=point(link.getBoundingClientRect(),'left'),c=point(link.getBoundingClientRect(),'right'),d=point(child.getBoundingClientRect(),'left');for(const [start,end] of [[a,b],[c,d]]){const bend=Math.max(12,(end.x-start.x)*.45);paths.push(`<path d="M${start.x} ${start.y} C${start.x+bend} ${start.y},${end.x-bend} ${end.y},${end.x} ${end.y}" fill="none" stroke="#f2c56e" stroke-width="2.5"/>`)}}const w=board.scrollWidth,h=board.scrollHeight;svg.style.width=w+'px';svg.style.height=h+'px';svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=paths.join('')}
function drawLines(){let board=$('#map-board'),svg=$('#map-lines');if(!board)return;let br=board.getBoundingClientRect(),paths=[];for(let s of project.scenes){let a=board.querySelector(`[data-node="${s.id}"]`);if(!a)continue;let ar=a.getBoundingClientRect();for(let c of s.choices){let choiceRow=a.querySelector(`[data-node-choice="${CSS.escape(c.id)}"]`);let row=choiceRow?.getBoundingClientRect();let b=board.querySelector(`[data-node="${c.target}"]`);if(!b)continue;let cr=b.getBoundingClientRect(),x1=ar.right-br.left,y1=(row?row.top+row.height/2:ar.top+ar.height/2)-br.top,x2=cr.left-br.left,y2=cr.top+cr.height/2-br.top;paths.push(`<path d="M${x1} ${y1} C${x1+35} ${y1},${x2-35} ${y2},${x2} ${y2}" fill="none" stroke="#d6ae73" stroke-width="2" opacity=".72"/><circle cx="${x2}" cy="${y2}" r="3" fill="#efc281"/>`)}}svg.setAttribute('viewBox',`0 0 ${board.scrollWidth} ${board.scrollHeight}`);svg.innerHTML=paths.join('')}
function assetName(kind,key){return project.assetNames?.[kind]?.[key]||key}
function assetColor(kind,key){const value=project.assetColors?.[kind]?.[key];return /^#[0-9a-fA-F]{6}$/.test(value||'')?value:''}
function characterDesign(key){const value=project.characterDesigns?.[key]||{};return {accent:/^#[0-9a-fA-F]{6}$/.test(value.accent||'')?value.accent:'',scale:Math.min(140,Math.max(70,Number(value.scale)||100)),flip:!!value.flip,glow:!!value.glow,carry:carriedObjects.includes(value.carry)?value.carry:'None'}}
function characterStyle(key){const d=characterDesign(key);return `--character-scale:${d.scale/100};--character-facing:${d.flip?-1:1};--character-glow:${d.glow?'drop-shadow(0 0 12px #5cefff) drop-shadow(0 0 3px #fff)':'drop-shadow(6px 6px 0 #000)'}`}
function characterCarry(key,mode){const d=characterDesign(key);return d.carry!=='None'?`<div class="character-carry carry-${mode}" aria-label="Carrying ${escape(d.carry)}">${propMarkup(d.carry)}</div>`:''}
function assetSettings(kind,key){if(!key||key==='None'||key==='Custom')return '';const isLocation=kind==='location',url=isLocation?`assets/${backdrops[key]||backdrops.Forest}`:`assets/${portraits[key]||portraits.Traveller}`,color=assetColor(kind,key),design=characterDesign(key);return `<div class="asset-settings"><div class="asset-settings-preview ${isLocation?'place-preview':'actor-preview'}" style="--asset-color:${escape(color||'#b05cff')};${isLocation?'':characterStyle(key)}"><img src="${escape(url)}" data-tint-kind="${kind}" data-tint-key="${escape(key)}" alt="">${isLocation?'':characterCarry(key,'preview')}</div><div class="asset-settings-fields"><strong>Edit ${isLocation?'location':'character'} · ${escape(key)}</strong><div class="field-grid"><div class="field"><label>Name</label><input data-asset-name="${kind}" data-asset-key="${escape(key)}" value="${escape(assetName(kind,key))}" maxlength="40"></div><div class="field"><label>${isLocation?'Colour':'Main colour'}</label><input type="color" data-asset-color="${kind}" data-asset-key="${escape(key)}" value="${escape(color||'#b05cff')}"></div></div><button type="button" class="btn sm ghost" data-reset-color="${kind}" data-asset-key="${escape(key)}" ${color?'':'disabled'}>Use original colours</button>${isLocation?'':`<div class="character-options"><div class="field-grid"><div class="field"><label>Detail colour</label><input type="color" data-character-option="accent" data-asset-key="${escape(key)}" value="${escape(design.accent||'#ffe44d')}"></div><div class="field"><label>Carried object</label><label class="carry-search-label">Find an object<input type="search" data-carry-search="${escape(key)}" placeholder="Search ${carriedObjects.length-1} objects…" autocomplete="off"></label><p class="selected-carry">Selected: ${escape(design.carry)}</p><div class="carry-picker" role="group" aria-label="Carried object">${carriedObjects.map(item=>`<button type="button" class="carry-choice ${design.carry===item?'selected':''}" data-carry-choice="${escape(item)}" data-asset-key="${escape(key)}" aria-pressed="${design.carry===item}"><span class="carry-choice-art" aria-hidden="true">${item==='None'?'×':propMarkup(item)}</span><span>${escape(item)}</span></button>`).join('')}</div></div></div><button type="button" class="btn sm ghost" data-clear-accent="${escape(key)}" ${design.accent?'':'disabled'}>Remove detail colour</button><div class="field"><label>Character size <output data-scale-output="${escape(key)}">${design.scale}%</output></label><input type="range" min="70" max="140" step="5" data-character-option="scale" data-asset-key="${escape(key)}" value="${design.scale}"></div><div class="character-checks"><label><input type="checkbox" data-character-option="flip" data-asset-key="${escape(key)}" ${design.flip?'checked':''}> Face the other way</label><label><input type="checkbox" data-character-option="glow" data-asset-key="${escape(key)}" ${design.glow?'checked':''}> Magical glow</label></div></div>`}</div></div>`}
const tintCache=new Map();
function tintedSprite(url,color,accent=''){const cacheKey=url+'|'+color+'|'+accent;if(tintCache.has(cacheKey))return tintCache.get(cacheKey);const promise=new Promise(resolve=>{const source=new Image();source.onload=()=>{try{const canvas=document.createElement('canvas');canvas.width=source.naturalWidth;canvas.height=source.naturalHeight;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);const primary=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16)),secondary=accent?[1,3,5].map(i=>parseInt(accent.slice(i,i+2),16)):null;for(let i=0;i<pixels.data.length;i+=4){if(pixels.data[i+3]<8)continue;const r=pixels.data[i],g=pixels.data[i+1],b=pixels.data[i+2],light=(r*.26+g*.58+b*.16)/255;const shade=Math.min(1.8,Math.pow(light,1.1)*1.7+.08);const useAccent=secondary&&light>.32&&((Math.max(r,g,b)-Math.min(r,g,b)>55&&((r>g*1.22)||(b>g*1.42)))||light>.75);const rgb=useAccent?secondary:primary;for(let channel=0;channel<3;channel++)pixels.data[i+channel]=Math.min(255,rgb[channel]*shade)}ctx.putImageData(pixels,0,0);resolve(canvas.toDataURL('image/png'))}catch{resolve(url)}};source.onerror=()=>resolve(url);source.src=url});tintCache.set(cacheKey,promise);return promise}
function applyAssetColours(){app.querySelectorAll('img[data-tint-kind][data-tint-key]').forEach(async img=>{const kind=img.dataset.tintKind,key=img.dataset.tintKey,color=assetColor(kind,key),accent=kind==='character'?characterDesign(key).accent:'';img.dataset.originalSrc||=img.getAttribute('src');const original=img.dataset.originalSrc;if(!color&&!accent){img.src=original;return}const recolored=await tintedSprite(original,color||'#b05cff',accent);if(img.isConnected&&assetColor(kind,key)===color&&(kind!=='character'||characterDesign(key).accent===accent))img.src=recolored})}
function renderKeepingDetails(){const opened=[...app.querySelectorAll('details')].map((el,i)=>el.open?i:-1).filter(i=>i>=0);render();const details=[...app.querySelectorAll('details')];opened.forEach(i=>{if(details[i])details[i].open=true})}
function visualChoice(label,key,values,current){return `<div class="field"><label>${label}</label><select data-visual="${key}">${values.map(x=>`<option value="${escape(x)}" ${current===x?'selected':''}>${escape((key==='location'||key==='actor')?assetName(key==='location'?'location':'character',x):x)}</option>`).join('')}</select></div>`}
function visualMarkup(s,preview=false){const v=s.visual||{location:s.background||project.background,actor:s.portrait||project.portrait,prop:'None',time:'Night',mood:'Mysterious'},bg=background(s),actorUrl=v.actor==='Custom'?portrait(s):`assets/${portraits[v.actor]||portraits.Traveller}`,placeColor=assetColor('location',v.location),personColor=assetColor('character',v.actor);const actor=v.actor==='None'?'':`<img class="visual-actor" style="${characterStyle(v.actor)}" src="${escape(actorUrl)}" data-tint-kind="character" data-tint-key="${escape(v.actor)}" alt="">${characterCarry(v.actor,'scene')}`;return `<div class="visual-composition visual-time-${escape(v.time||'Night')} visual-mood-${escape(v.mood||'Mysterious')} ${preview?'visual-preview':''}" style="--visual-backdrop:url('${escape(bg)}')"><div class="visual-backdrop"></div>${placeColor?`<div class="visual-location-color" style="--location-color:${escape(placeColor)}"></div>`:''}${actor}${v.prop&&v.prop!=='None'?`<div class="visual-object">${propMarkup(v.prop)}</div>`:''}<div class="visual-vignette"></div><div class="visual-caption"><span data-asset-name-view="location:${escape(v.location)}">${escape(assetName('location',v.location))}</span>${v.actor!=='None'?`<span data-asset-name-view="character:${escape(v.actor)}">${escape(assetName('character',v.actor))}</span>`:''}</div></div>`}

function sceneVisualEditor(s){const v=s.visual||{location:s.background||project.background,actor:s.portrait||project.portrait,prop:'None',time:'Night',mood:'Mysterious'};return `<div class="visual-builder"><div class="visual-builder-head"><div><div class="eyebrow">Scene visual</div><h3>Show what happens here</h3><p class="muted">Set the place, person and important object. The picture appears in the game.</p></div><button class="btn sm" data-action="suggest-visual" type="button">Suggest from scene text</button></div>${visualMarkup(s,true)}<div class="visual-builder-grid">${visualChoice('Important object','prop',sceneProps,v.prop)}${visualChoice('Time of day','time',sceneTimes,v.time)}${visualChoice('Mood','mood',sceneMoods,v.mood)}</div><p class="visual-tip">Tip: a lantern can show hope or danger. Choose the detail your player should notice first.</p></div>`}
function blockAssetControls(s){const place=s.visual?.location||s.background||project.background,actor=s.visual?.actor||s.portrait||project.portrait;return `<div class="block-edit-details"><details class="block-asset-panel"><summary>Edit place name & colour</summary>${assetSettings('location',place)||'<p>Choose a place above to edit it.</p>'}</details><details class="block-asset-panel"><summary>Edit character name & appearance</summary>${assetSettings('character',actor)||'<p>Choose a character above to edit it.</p>'}</details></div>`}
function sceneEditor(s){if(!s)return '';return `<div class="section-head"><h3>${s.type==='ending'?'Ending':'Scene'}: ${escape(s.title)}</h3>${s.id!==project.opening?`<button class="btn sm danger" data-delete-scene="${s.id}">Delete</button>`:''}</div>${s.id!==project.opening?`<div class="field block-type-select"><label for="block-type-${s.id}">What happens after this box?</label><select id="block-type-${s.id}" data-scene-type="${s.id}"><option value="scene" ${s.type==='scene'?'selected':''}>Scene · story continues</option><option value="ending" ${s.type==='ending'?'selected':''}>Ending · story finishes</option></select><p class="muted">Choose Scene to add more choices and keep this path going.</p></div>`:''}<div class="field"><label>Scene title</label><input data-scene="title" value="${escape(s.title)}"></div><div class="block-look"><div class="block-look-controls"><h3>Scene and character</h3><p>Choose what your player sees here.</p><div class="block-look-fields">${visualChoice('Place','location',sceneLocations,s.visual?.location||s.background||project.background)}${visualChoice('Character','actor',sceneCharacters,s.visual?.actor||s.portrait||project.portrait)}</div></div><div class="block-look-preview">${visualMarkup(s,true)}</div></div>${blockAssetControls(s)}<div class="field"><label>What happens?</label><textarea data-scene="text">${escape(s.text)}</textarea></div><div class="field"><label>Question for the player</label><input data-scene="question" value="${escape(s.question??'What do you do?')}" placeholder="What do you do?"></div>${sceneEffectPicker(s)}<details class="optional"><summary>More visuals, dialogue and sound</summary><div class="field"><label>Character dialogue (optional)</label><textarea data-scene="dialogue" placeholder="“Don't open the door.”">${escape(s.dialogue||'')}</textarea></div><div class="field-grid"><div class="field"><label>Who speaks?</label><input data-scene="speaker" value="${escape(s.speaker||'')}" placeholder="A stranger"></div><div class="field"><label>Another character in the scene</label><select data-scene="supporting">${['None',...Object.keys(portraits)].map(x=>`<option ${s.supporting===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field-grid"><div class="field"><label>Music</label><select data-scene="music">${['Use story theme',...musicTracks].map(x=>`<option value="${x==='Use story theme'?'':x}" ${(s.music||'')===(x==='Use story theme'?'':x)?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Sound effect</label><select data-scene="sound">${['None','Chime','Sparkle','Signal','Door','Footsteps','Wind','Rain','Thunder','Heartbeat'].map(x=>`<option ${s.sound===x?'selected':''}>${x}</option>`).join('')}</select></div></div>${sceneVisualEditor(s)}</details>`}
function effectSummary(c){return c.effects.map(e=>`${e.kind==='trait'?'+':''}${escape(e.key)}`).join(' · ')||'No consequence yet'}
const effectPresets={'':'No extra effect','trait:Courage':'+ Courage','trait:Empathy':'+ Empathy','trait:Curiosity':'+ Curiosity','trait:Cunning':'+ Cunning','inventory:Lantern':'Gain a lantern','inventory:Map':'Gain a map','relationship:Wolf':'Befriend the wolf','flag:Secret discovered':'Discover a secret','appearance:New scar':'Gain a scar'};
function createChoiceDestination(source,choice,ending=false){const next={id:id('s'),title:ending?'New ending':'New scene',text:ending?'Describe how the journey ends.':'What happens after this choice?',background:source.background,portrait:source.portrait,visual:source.visual?{...source.visual}:undefined,dialogue:'',question:'What do you do?',motion:'None',sound:'None',type:ending?'ending':'scene',choices:[]};project.scenes.push(next);choice.target=next.id;return next}
function choiceEditor(s){if(!s)return '';return s.choices.map((c,i)=>{let current=c.effects.length===1?`${c.effects[0].kind}:${c.effects[0].key}`:c.effects.length?'custom':'';return `<div class="choice-row"><div class="rowhead"><strong>Choice ${i+1}</strong><button class="btn sm danger" data-delete-choice="${c.id}">Remove</button></div><div class="field"><label>What does the player choose?</label><input data-choice="${c.id}" data-prop="text" value="${escape(c.text)}" placeholder="e.g. Help the wolf"></div><div class="field"><label>What happens after this choice?</label><select data-choice="${c.id}" data-prop="target"><option value="__new_scene">＋ Create a new scene</option><option value="__new_ending">＋ Create a new ending</option><optgroup label="Or connect to an existing block">${project.scenes.filter(dest=>dest.id!==s.id).map(dest=>`<option value="${dest.id}" ${c.target===dest.id?'selected':''}>${escape(dest.title)}${dest.type==='ending'?' (ending)':''}</option>`).join('')}</optgroup></select></div><details class="optional"><summary>Consequences and unlock rules</summary><div class="field"><label>What does it change?</label><select data-quick-effect="${c.id}">${Object.entries(effectPresets).map(([value,label])=>`<option value="${value}" ${current===value?'selected':''}>${label}</option>`).join('')}${current==='custom'?'<option value="custom" selected>Custom effects</option>':''}</select></div><p class="muted">Require an item, trait, relationship or story event before this choice appears.</p><div class="field-grid"><div class="field"><label>Unlock only if...</label><select data-choice="${c.id}" data-prop="conditionKind"><option value="" ${!c.condition?.kind?'selected':''}>Always available</option>${['inventory','trait','relationship','flag'].map(k=>`<option value="${k}" ${c.condition?.kind===k?'selected':''}>Has ${k==='trait'?'trait points':k}</option>`).join('')}</select></div><div class="field"><label>Required name</label><input data-choice="${c.id}" data-prop="conditionKey" placeholder="e.g. Lantern" value="${escape(c.condition?.key||'')}"></div></div><label>Custom consequences</label>${c.effects.map((e,j)=>`<div class="field-grid" style="margin-bottom:.45rem"><select data-effect="${c.id}" data-index="${j}" data-prop="kind">${['trait','inventory','relationship','flag','appearance'].map(k=>`<option ${e.kind===k?'selected':''}>${k}</option>`).join('')}</select><input data-effect="${c.id}" data-index="${j}" data-prop="key" placeholder="Name or detail" value="${escape(e.key)}"></div>`).join('')}<button class="btn sm" data-add-effect="${c.id}">＋ Add another effect</button></details></div>`}).join('')||'<p class="note">Add a choice to create the next scene or ending automatically.</p>'}
function inspector(){const s=scene(selected);return `<div class="eyebrow">Live story preview</div><div class="card"><div class="eyebrow">${escape(project.genre)} / ${escape(project.world)}</div><h2>${escape(project.title)}</h2><p>${escape(project.description)}</p><small>${escape(project.hook)}</small></div><h3>Selected scene</h3>${s?`<div class="card">${sceneEditor(s)}</div>${s.type==='scene'?`<h3>Choice paths</h3>${s.choices.map(c=>`<div class="choice-row"><strong>${escape(c.text)}</strong><p class="muted" style="margin:.4rem 0">→ ${escape(scene(c.target)?.title||'Missing scene')}</p><small>${effectSummary(c)}</small></div>`).join('')}<button class="btn sm" data-action="add-choice">＋ Add choice</button>`:''}`:'<p>Select a scene on the map.</p>'}<hr><div class="note">Teaching tip: ask a friend what their choices revealed about the character. If they cannot tell, strengthen a consequence or rewrite the scene.</div>`}
function issues(){let out=[];if(!project.scenes.some(s=>s.type==='ending'))out.push('Add at least one ending.');for(let s of project.scenes){if(s.type==='scene'&&!s.choices.length)out.push(`“${s.title}” has no choices.`);for(let c of s.choices)if(!scene(c.target))out.push(`A choice in “${s.title}” has no destination.`)}return out}
function blankPlay(){return {current:project.opening,traits:{},inventory:{},relationships:{},flags:{},appearance:[],path:[],turns:0}}
function available(c){const req=c.condition;if(req?.all)return req.all.every(rule=>available({condition:rule}));if(req?.any)return req.any.some(rule=>available({condition:rule}));if(!req?.kind||!req.key)return true;let bag=req.kind==='trait'?play.traits:req.kind==='inventory'?play.inventory:req.kind==='relationship'?play.relationships:play.flags;const present=(bag[req.key]||0)>=(Math.max(1,Number(req.min)||1));return req.not?!present:present}
function background(s){if(s.visual?.location==='Custom'&&project.customBackground?.startsWith('data:image/'))return project.customBackground;if(!featured&&backdrops[s.visual?.location])return `/assets/${backdrops[s.visual.location]}`;if(featured&&/^(crown|pip|city|clock|blackwater|moonberry)-[a-z-]+\.webp$/.test(s.art||''))return `/assets/${s.art}`;return s.background==='Custom'&&project.customBackground?.startsWith('data:image/')?project.customBackground:`/assets/${backdrops[s.background]||backdrops[project.background]||backdrops.Forest}`}
function portrait(s){if(!featured&&s.visual?.actor&&portraits[s.visual.actor])return `assets/${portraits[s.visual.actor]}`;return s.portrait==='Custom'&&project.customPortrait?.startsWith('data:image/')?project.customPortrait:`assets/${portraits[s.portrait]||portraits[project.portrait]||portraits.Traveller}`}
function motionFor(s){if(s.motion)return s.motion;const text=(s.title+' '+s.text).toLowerCase();if(/\b(rain|storm|downpour)\b/.test(text))return 'Rain';if(/\b(snow|blizzard|frost)\b/.test(text))return 'Snow';if(/\b(fire|flame|burning|embers)\b/.test(text))return 'Embers';if(/\b(fog|mist|smoke)\b/.test(text))return 'Mist';if(/\b(wind|breeze)\b/.test(text))return 'Wind';return 'None'}
function playerIdentity(){const ranked=Object.entries(play.traits||{}).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]);const top=ranked[0]?.[0]||'';const names={Courage:'The Brave',Empathy:'The Kind',Curiosity:'The Explorer',Cunning:'The Clever',Kindness:'The Kind',Silliness:'The Joyful'};return {title:names[top]||project.heroName||'The Adventurer',top,ranked}}
function choiceRecap(){return (play.path||[]).slice(-3).map((step,i)=>`<li><span>${String(Math.max(1,play.path.length-2+i)).padStart(2,'0')}</span><strong>${escape(step.choice)}</strong></li>`).join('')}
function player(){const s=scene(play?.current)||scene(project.opening);if(!s)return `<p>Story unavailable.</p>`;const locationKey=s.visual?.location||s.background||project.background,actorKey=s.visual?.actor||s.portrait||project.portrait,ending=s.type==='ending',traits=Object.entries(play.traits).sort((a,b)=>b[1]-a[1]),items=Object.keys(play.inventory).filter(k=>play.inventory[k]>0),relations=Object.keys(play.relationships).filter(k=>play.relationships[k]>0),choices=s.choices.filter(available);return `<div class="novel-screen ${featured?'featured-novel':''} ${featuredKind==='pip'||featuredKind==='moonberry'?'pip-novel':''} ${featuredKind==='city'||featuredKind==='clock'?'soft-pixel-novel':''}"><div class="novel-book" id="novelBook"><div class="novel-stage motion-${escape(motionFor(s))} ${!featured&&s.visual?`visual-time-${escape(s.visual.time||'Night')} visual-mood-${escape(s.visual.mood||'Mysterious')}`:''}" style="--scene-image:url('${escape(background(s))}')"><div class="novel-scenery"></div>${!featured&&assetColor('location',locationKey)?`<div class="novel-location-color" style="--location-color:${escape(assetColor('location',locationKey))}"></div>`:''}${!featured&&s.visual?.prop&&s.visual.prop!=='None'?`<div class="visual-stage-prop">${propMarkup(s.visual.prop)}</div>`:''}<div class="novel-atmosphere" aria-hidden="true"></div><div class="novel-light"></div><div class="novel-particles" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div>${featured?'<button class="preview-exit" data-action="featured-games">← Adventures</button>':!published?'<button class="preview-exit" data-action="edit">← Back to story map</button>':''}<button class="music-toggle" data-action="music-toggle" type="button" aria-label="${musicEnabled?'Mute music':'Play music'}" aria-pressed="${musicEnabled}">${musicEnabled?'♫ Music on':'♪ Play music'}</button><header class="novel-chapter"><span>${escape(project.title)} · ${escape(project.heroName||'Your hero')}</span><span>${ending?'ENDING':`SCENE ${String(play.turns+1).padStart(2,'0')}`}</span></header>${!featured&&play.turns?`<div class="play-progress" aria-label="Your journey so far"><span>${play.turns} choice${play.turns===1?'':'s'} made</span>${playerIdentity().top?`<strong>${escape(playerIdentity().top)} is taking shape</strong>`:''}</div>`:''}${!featured&&actorKey==='None'?'':`<img class="novel-character" style="${characterStyle(actorKey)}" src="${escape(portrait(s))}" data-tint-kind="character" data-tint-key="${escape(actorKey)}" alt="Character in this scene">${!featured?characterCarry(actorKey,'game'):''}`}${!featured?`<div class="novel-scene-identity"><span data-asset-name-view="location:${escape(locationKey)}">${escape(assetName('location',locationKey))}</span>${actorKey&&actorKey!=='None'?`<span data-asset-name-view="character:${escape(actorKey)}">${escape(assetName('character',actorKey))}</span>`:''}</div>`:''}${s.supporting&&s.supporting!=='None'&&portraits[s.supporting]?`<img class="novel-support" src="assets/${portraits[s.supporting]}" alt="${escape(s.supporting)} in this scene">`: ''}${play.appearance.length?`<div class="novel-details">${play.appearance.map(x=>`<span>${escape(x)}</span>`).join('')}</div>`:''}<div class="novel-dialogue"><div class="novel-label"><span class="novel-diamond">✦</span>${ending?'The story concludes':'Narrator'}</div><h1>${escape(s.title)}</h1><p class="novel-text" id="novelText" data-full="${escape(s.text)}" aria-label="${escape(s.text)}" aria-hidden="false"></p>${s.dialogue?`<p class="novel-dialogue-line" id="novelDialogue" hidden>${s.speaker?`<strong>${escape(s.speaker)}:</strong> `:''}“${escape(s.dialogue)}”</p>`:''}<div class="novel-read-controls"><span id="readingHint">The story is unfolding…</span><button type="button" class="novel-skip" id="skipNarration">Show full text ↠</button></div></div></div><div class="novel-next" id="novelNext" hidden>${ending&&featuredKind==='moonberry'?`<div class="novel-ending moonberry-ending"><div class="eyebrow">Your adventure</div><h2>${escape(s.title)}</h2><p><strong>${(play.traits.Kindness||0)>=(play.traits.Silliness||0)?'Pip the Kind':'Pip the Funny'}</strong> · Your special power: ${(play.traits.Kindness||0)>=(play.traits.Silliness||0)?'KINDNESS':'GIGGLES'} ⭐</p><p>You helped ${relations.filter(x=>x!=='Muffin').length} forest friend${relations.filter(x=>x!=='Muffin').length===1?'':'s'} and found ${items.filter(x=>!['Big Backpack','Biscuit'].includes(x)).length} special thing${items.filter(x=>!['Big Backpack','Biscuit'].includes(x)).length===1?'':'s'}.</p><div class="inline-actions"><button class="btn primary" data-action="restart">↻ Play again</button><button class="btn" data-action="create-game">✦ Create your own story</button></div></div>`:ending?`<div class="novel-ending"><div class="eyebrow">Your choices shaped the story</div><h2>${featured?escape(s.title):`You became: ${escape(playerIdentity().title)}`}</h2><p class="ending-outcome">${escape(s.text)}</p>${playerIdentity().top?`<div class="identity-card"><span>Strongest trait</span><strong>${escape(playerIdentity().top)}</strong><small>Your decisions built this character as you played.</small></div>`:''}<div class="ending-stats">${traits.length?`<div><span>Traits</span><strong>${traits.map(([k,v])=>`${escape(k)} ${v}`).join(' · ')}</strong></div>`:''}${items.length?`<div><span>Carried</span><strong>${items.map(escape).join(', ')}</strong></div>`:''}${relations.length?`<div><span>Connections</span><strong>${relations.map(escape).join(', ')}</strong></div>`:''}</div>${play.path.length?`<div class="choice-recap"><span class="eyebrow">Choices that brought you here</span><ol>${choiceRecap()}</ol></div>`:''}<p class="novel-path">${[...play.path.map(x=>scene(x.from)?.title),s.title].filter(Boolean).map(escape).join(' → ')}</p><div class="inline-actions"><button class="btn" data-action="restart">Play again</button><button class="btn" data-action="try-path">Try a different path</button>${published||featured?`<button class="btn primary" data-action="challenge">Share game →</button>`:`<button class="btn primary" data-action="edit">Improve a branch →</button>`}</div></div>`:choices.length?`<div class="novel-prompt">${escape(s.question||'What do you do?')}</div><div class="novel-choice-list">${choices.map((c,i)=>`<button class="novel-choice" data-play-choice="${c.id}" style="--order:${i}"><span class="choice-num">${String(i+1).padStart(2,'0')}</span><span>${escape(c.text)}</span><span aria-hidden="true">↗</span></button>`).join('')}</div>`:`<div class="note">There are no available choices here. ${published?'This story ends here.':'Return to the editor to fix this branch.'}</div>`}</div></div></div>`}
let narrationTimer=0,narrationToken=0;
function finishNarration(){clearTimeout(narrationTimer);narrationToken++;const text=$('#novelText'),next=$('#novelNext');if(!text||!next)return;text.textContent=text.dataset.full;next.hidden=false;$('#novelDialogue')?.removeAttribute('hidden');$('#novelBook')?.classList.add('has-choices');$('#readingHint').textContent='Choose what happens next';$('#skipNarration').hidden=true}
function startNarration(){const text=$('#novelText');if(!text)return;const full=Array.from(text.dataset.full||'');let i=0,token=++narrationToken;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(reduced){finishNarration();return}function tick(){if(token!==narrationToken)return;i=Math.min(full.length,i+2);text.textContent=full.slice(0,i).join('');if(i>=full.length){finishNarration();return}narrationTimer=setTimeout(tick,30)}narrationTimer=setTimeout(tick,350)}
let musicEnabled=false,musicInteracted=false,musicAudio=null,musicPlaying='';
function stopMusic(){if(musicAudio){musicAudio.pause();musicAudio.currentTime=0;musicAudio=null}musicPlaying=''}
function syncMusic(){if(!musicEnabled)return;const current=view==='play'?scene(play?.current):view==='edit'&&stage==='Story'?scene(selected):null,chosen=view==='play'||view==='edit'||view==='ready'?(current?.music||project.music||'Dungeon'):'Menu';if(chosen==='None'){stopMusic();return}if(musicAudio&&musicPlaying===chosen){if(musicAudio.paused)musicAudio.play().catch(()=>{});return}stopMusic();musicPlaying=chosen;musicAudio=new Audio(`assets/music-${chosen.toLowerCase()}.mp3`);musicAudio.loop=true;musicAudio.volume=.32;musicAudio.play().catch(()=>{musicEnabled=false;stopMusic();const button=$('.music-toggle, .menu-music-btn');if(button){button.textContent='♪ Play music';button.setAttribute('aria-pressed','false');button.setAttribute('aria-label','Play music')}})}
let gameAudio;
function playSceneSound(name){if(!musicEnabled||!name||name==='None')return;try{gameAudio??=new (window.AudioContext||window.webkitAudioContext)();if(gameAudio.state==='suspended')gameAudio.resume().catch(()=>{});const ctx=gameAudio,now=ctx.currentTime;const tones={Select:[[560,.07],[760,.09]],Reveal:[[190,.11],[300,.16]],Chime:[[660,.18],[880,.24]],Signal:[[420,.13],[350,.2]],Door:[[135,.12],[85,.18]],Sparkle:[[660,.09],[990,.1],[1320,.16]],Heartbeat:[[95,.12],[75,.16]]};if(name==='Wind'||name==='Rain'||name==='Thunder'||name==='Footsteps'||name==='Door'){const duration=name==='Thunder'?.7:name==='Wind'?.65:name==='Rain'?.55:.15,length=Math.ceil(ctx.sampleRate*duration),buffer=ctx.createBuffer(1,length,ctx.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<length;i++)samples[i]=(Math.random()*2-1)*(name==='Footsteps'?(i%Math.floor(ctx.sampleRate*.15)<ctx.sampleRate*.035?1:.03):1);const noise=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();noise.buffer=buffer;filter.type=name==='Thunder'||name==='Wind'||name==='Door'?'lowpass':'highpass';filter.frequency.value=name==='Thunder'?270:name==='Wind'?480:name==='Door'?750:2100;gain.gain.setValueAtTime(.0001,now);gain.gain.linearRampToValueAtTime(name==='Thunder'?.095:name==='Door'?.045:.025,now+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);noise.connect(filter);filter.connect(gain);gain.connect(ctx.destination);noise.start(now);noise.stop(now+duration)}(tones[name]||[]).forEach(([frequency,duration],i)=>{const oscillator=ctx.createOscillator(),gain=ctx.createGain(),at=now+i*.11;oscillator.type=name==='Select'||name==='Signal'?'square':'triangle';oscillator.frequency.setValueAtTime(frequency,at);if(name==='Reveal'||name==='Door')oscillator.frequency.exponentialRampToValueAtTime(Math.max(40,frequency*.6),at+duration);gain.gain.setValueAtTime(.0001,at);gain.gain.linearRampToValueAtTime(name==='Select'?.022:.035,at+.012);gain.gain.exponentialRampToValueAtTime(.0001,at+duration);oscillator.connect(gain);gain.connect(ctx.destination);oscillator.start(at);oscillator.stop(at+duration)})}catch{}}

function setProjectProp(key,value){project[key]=value;save()}
function applyChoice(c){const current=scene(play.current);for(const e of c.effects||[]){if(!e.key)continue;if(e.kind==='appearance'){if(!play.appearance.includes(e.key))play.appearance.push(e.key)}else{const bag=e.kind==='trait'?play.traits:e.kind==='inventory'?play.inventory:e.kind==='relationship'?play.relationships:play.flags;bag[e.key]=(bag[e.key]||0)+(e.amount||1)}}play.path.push({from:current.id,id:c.id,choice:c.text,to:c.target});play.current=c.target;play.turns++}
function choose(c){if(!musicEnabled&&!musicInteracted){musicEnabled=true}const button=document.querySelector('[data-play-choice="'+CSS.escape(c.id)+'"]');button?.classList.add('chosen');document.querySelectorAll('[data-play-choice]').forEach(el=>el.disabled=true);playSceneSound('Select');if(featuredKind==='city'&&c.target==='betrayal_check'){const destination=(play.flags['Mira lied']||0)>=2?'mira_betrayal':(play.flags['Tomas ignored']||0)>=2?'tomas_betrayal':(play.flags['Seren dismissed']||0)>=1?'seren_betrayal':'together';c={...c,target:destination};if(destination!=='together')play.flags.Betrayal=1}const sceneSound=scene(c.target)?.sound||'Reveal';applyChoice(c);render();setTimeout(()=>playSceneSound(sceneSound),170)}
